export const GRAM_EN = {
  "g04": {"title": "The sound shifts (the key to everything)", "summary": "If you know German, 70% of Swiss German is applying 6 transformation rules.", "points": ["**k → ch**: Kind → **Ch**ind · kaufen → **ch**aufe · kalt → **ch**alt · können → **ch**öne", "**au → uu**: Haus → H**uu**s · auf → **u**f · kaufen → ch**au**fe (this one stays!)", "**ei → ii**: Wein → W**ii** · Zeit → Z**ii**t · mein → m**ii**n · weiss → weiss (stays)", "**-en → -e**: machen → mach**e** · Wochen → Wuch**e**", "**-st → -sch**: bist → bi**sch** · ist → i**sch** · fast → fa**sch**t", "**-ung → -ig**: Wohnung → Wohn**ig** · Sitzung → Sitz**ig** · Zeitung → Ziit**ig**"], "ex": {"g04e1": {"q": "Into dialect: \"die Küche\" → d ___", "why": "k → ch and final -e: Küche → Chuchi."}, "g04e2": {"q": "Into dialect: \"das Haus\" → s ___", "why": "au → uu: Haus → Huus."}, "g04e3": {"q": "Into dialect: \"die Wohnung\" → d ___", "why": "-ung → -ig: Wohnung → Wohnig."}, "g04e4": {"q": "How do you say \"kalt\" in Züridütsch?", "options": ["kalt", "chalt", "chuld"], "why": "k → ch: kalt → chalt."}, "g04e5": {"q": "\"der Wein\" in dialect is...", "options": ["de Wein", "de Wii", "de Wiin"], "why": "ei → ii: Wein → Wii."}, "g04e6": {"q": "Into dialect: \"die Zeit\" → d ___", "why": "ei → ii: Zeit → Ziit."}, "g04e7": {"q": "\"nicht\" in the Zurich dialect is...", "options": ["nicht", "nöd", "net"], "why": "Zurich says \"nöd\". Bern says \"nid\", Basel \"nit\"."}}},
  "s07": {"title": "The falling diphthongs ie, ue, üe", "summary": "From the class on 19/08. Two sounds in a row, falling from high to low. Without them you don’t sound Swiss.", "points": ["They are not a long vowel: they are **two sounds**, and the second one falls. Bi-er, Blue-me, Brüe-der.", "The mnemonic from class: «Mit em **ÜE** han i **Müe**, s **UE** git mer z **tue**, und s **IE** graatet **nie**.»", "**ie** — B**ie**r, Br**ie**f, Chr**ie**si (cherry), D**ie**b, T**ie**r, v**ie**r, w**ie**, n**ie**, l**ie**cht", "**ue** — Bl**ue**me, B**ue**b, B**ue**ch, Ch**ue**, Ch**ue**che, F**ue**ss, M**ue**ter, St**ue**l, g**ue**t, gn**ue**g, s**ue**che, l**ue**ge", "**üe** — Br**üe**der, Ch**üe**, Fr**üe**lig, F**üe**ss, Gm**üe**s, m**üe**d, gr**üe**n, gr**üe**zi, m**üe**se", "Tongue-twister from class: «De D**ie**b fl**ie**t vor v**ie**r l**ie**be St**ie**rli.»", "«M**ue**ter t**ue** d G**ue**tslibüchs gn**ue**g g**ue**t z**ue**!»", "«M**ii**n Br**üe**der f**üe**rt di m**üe**de Ch**üe** a d Ch**üe**li.»", "⚠️ Careful: **not** every German «ie» becomes a diphthong. *vier* → v**ie**r yes, but *sieben* → s**i**be and *Sieb* → S**ii**b, no."], "tableHead": ["Diphthong", "Examples", "Sounds like"], "ex": {"s07e1": {"q": "How is «guet» pronounced?", "options": ["gu-et, two sounds", "guuut, like a long u", "g-vet"], "why": "It is a falling diphthong: the u falls towards the e."}, "s07e2": {"q": "Hochdeutsch «Bruder» → dialect: Br___der", "why": "Brüeder, with üe."}, "s07e3": {"q": "Hochdeutsch «Kuchen» → dialect: Ch___che", "why": "Chueche."}, "s07e4": {"q": "Which of these has NO falling diphthong?", "options": ["müed", "sibe", "Blueme"], "why": "«sieben» → «sibe», with a plain i. Not every German ie converts."}, "s07e5": {"q": "What does the mnemonic say about ÜE?", "options": ["«han i Müe» (it’s hard for me)", "«git mer z tue»", "«graatet nie»"], "why": "Mit em ÜE han i Müe — precisely the hardest one."}, "s07e6": {"q": "Hochdeutsch «grün» → dialect: gr___n", "why": "grüen. Same as grüezi."}, "s07e7": {"q": "«Chriesi» means…", "options": ["war", "cherry", "crisis"], "why": "Chriesi = Kirsche. «Chrieg» is the one that means war: watch out."}}},
  "g05": {"title": "Articles: de, d, s", "summary": "The articles shrink drastically. The genders are the same as in German.", "points": ["Definite: **de** Maa (der) · **d** Frau (die) · **s** Chind (das)", "Indefinite: **en** Maa (ein) · **e** Frau (eine) · **es** Chind (ein)", "Definite plural: **d** — d Chind, d Lüüt.", "In speech they are often glued on: \"s Huus\" sounds like /sHuus/.", "If you already know the German gender, you know it in dialect. Nothing to relearn."], "tableHead": ["Gender", "Definite", "Indefinite"], "ex": {"g05e1": {"q": "___ Frau isch nätt. (definite article)", "why": "die → d."}, "g05e2": {"q": "___ Chind schlaft. (definite article)", "why": "das → s."}, "g05e3": {"q": "___ Maa chunt spöter.", "options": ["de", "d", "s"], "why": "der → de."}, "g05e4": {"q": "How do you say \"a flat\" (eine Wohnung)?", "options": ["en Wohnig", "e Wohnig", "es Wohnig"], "why": "Wohnung is feminine → e Wohnig."}, "g05e5": {"q": "How do you say \"a house\" (ein Haus)?", "options": ["en Huus", "e Huus", "es Huus"], "why": "Haus is neuter → es Huus."}, "g05e6": {"q": "___ Velo staht dusse. (definite article, das Velo)", "why": "Velo is neuter → s Velo."}}},
  "s01": {"title": "Indefinite article: en, e, es", "summary": "From the class on 19/08. German «ein» splits into three forms depending on gender.", "points": ["masculine **en** · feminine **e** · neuter **es**", "ein → **e** · ein → **en** · ein → **es** (all three come from the same «ein»)", "**en** Löffel · **e** Gable · **es** Mässer", "**en** Chochherd · **e** Pfanne · **es** Chochrezäpt", "Used just like in German: when you mention something for the first time, or any one of a kind.", "The feminine **e** has no -n. That is the classic mistake: «e Frau», not «en Frau»."], "tableHead": ["Gender", "Article", "Example from class"], "ex": {"s01e1": {"q": "Mir bruuched ___ Pass (m) zum reise.", "why": "Masculine → en."}, "s01e2": {"q": "D Leona bruucht ___ Massage (f) zum entspanne.", "why": "Feminine → e, without -n."}, "s01e3": {"q": "Was für ___ Schampoo (n) bruuchsch du?", "options": ["en", "e", "es"], "why": "Neuter → es."}, "s01e4": {"q": "De Andri bruucht ___ Helm (m) zum Skifahre.", "why": "Masculine → en."}, "s01e5": {"q": "Zum Ässe bruucht me ___ Gable (f).", "why": "Gable is feminine → e Gable."}, "s01e6": {"q": "Zum choche bruuch i ___ Chochrezäpt.", "options": ["en", "e", "es"], "why": "Chochrezäpt is neuter → es."}, "s01e7": {"q": "Ich bruuch ___ Fründin (f) zum glücklich sii.", "why": "Feminine → e."}, "s01e8": {"q": "Which mistake is the most typical?", "options": ["Using «es» for masculine", "Using «en» for feminine", "Using «e» for neuter"], "why": "The feminine is a bare «e». «en Frau» gives you away immediately."}}},
  "g06": {"title": "Negation: nöd and kei", "summary": "From the class on 02/09. Two words, two uses. Just like nicht/kein in German.", "points": ["**nöd** negates verbs, adjectives and whole sentences. It goes AFTER the conjugated verb.", "Ich verstahn **nöd**. · Das isch **nöd** guet. · Ich gang hüt **nöd** ge schaffe.", "**kein / kei / keis** negates nouns (= no, not any). It goes BEFORE the noun.", "masculine **kein** Stei · feminine **kei** Muus · neuter **keis** Buech · plural **kei**", "⚠️ The two books spell it differently, but it is the same thing: **Holle** uses kein/kei/keis and **Schorn** uses kän/kä/käs. Pick one and stick to it.", "Ich ha **kei** Ziit. · Es hät **keis** Brot meh. · Ich gseh **kein** Ries.", "Quick rule: if a noun without an article follows → kein/kei/keis. Otherwise → nöd.", "The verb negation varies by region too: Zurich **nöd**, Bern **nid**, elsewhere **ned** or **nit**."], "ex": {"g06e1": {"q": "Ich ha ___ Gäld (n).", "why": "Neuter → keis (Holle) or käs (Schorn). Both are fine."}, "g06e2": {"q": "Das isch ___ richtig.", "why": "Negates an adjective → nöd."}, "g06e3": {"q": "Ich verstahn ___.", "options": ["kei", "nöd", "nüüt"], "why": "Negates the verb → nöd. (\"Ich verstahn nüüt\" = I understand NOTHING, also correct but a different thing.)"}, "g06e4": {"q": "Er het ___ Auto (n).", "options": ["nöd", "keis", "nüüt"], "why": "Neuter noun → keis."}, "g06e5": {"q": "Mir gönd hüt ___ i d Stadt.", "why": "Negates the whole sentence → nöd, after the verb."}, "g06e6": {"q": "How do you say \"I don’t know\"?", "options": ["Ich weiss kei.", "Ich weiss nöd.", "Ich nöd weiss."], "why": "nöd ALWAYS goes after the conjugated verb, never before."}}},
  "s02": {"title": "Negative article: kän, kä, käs", "summary": "From the class on 19/08. «No/none» declines too, exactly like the indefinite article.", "points": ["masculine **kän** · feminine **kä** · neuter **käs** · plural **kä**", "Notice it follows the en/e/es pattern with a k- in front: **kän** / **kä** / **käs**.", "Ich ha **kän** Hunger. · Sie hät **käs** Gäld. · Es hät **kä** Milch.", "Er hät **kä** Brüeder und **kä** Schwöschter. (plural → kä)", "It works for countable and uncountable alike: **käs** Auto, **kän** Strom.", "Emphatic form, when you want to stress it: **käin** · **käi** · **käis**.", "An expression to learn: **uf kän Fall** = no way.", "You will also see «kei» written without declension. The course teaches the declined forms; use those."], "tableHead": ["Gender", "Indefinite", "Negative", "Emphatic"], "ex": {"s02e1": {"q": "Händ Ihr es Auto? — Nei, mir händ ___ Auto (n).", "why": "Neuter → käs."}, "s02e2": {"q": "De Strom isch uusgfalle. Mir händ ___ Strom (m).", "why": "Masculine → kän."}, "s02e3": {"q": "Wettsch öppis ässe? — Nei danke, ich ha ___ Hunger (m).", "options": ["kä", "kän", "käs"], "why": "Hunger is masculine → kän. It also works for uncountables."}, "s02e4": {"q": "Em Dario sini Familie isch arm. Sie hät ___ Gäld (n).", "why": "Gäld is neuter → käs."}, "s02e5": {"q": "Öise Chüehlschrank isch läär. Es hät ___ Milch (f) drin.", "why": "Feminine → kä."}, "s02e6": {"q": "De Gion isch es Einzelchind. Er hät ___ Brüeder und ___ Schwöschter.", "options": ["kän / kä", "kä / kä", "käs / käs"], "why": "Both are plural → kä."}, "s02e7": {"q": "Säisch mer, was passiert isch? — Nei, uf ___ Fall!", "why": "«uf kän Fall» = no way. Learn it whole."}, "s02e8": {"q": "Chan i au echli spöter choo? — Ja, das isch ___ Problem (n).", "options": ["kän", "kä", "käs"], "why": "Problem is neuter → käs Problem."}, "s02e9": {"q": "Ich ha welle go poschte, aber es hät ___ Gschäft (n) offe ghaa.", "why": "Gschäft is neuter → käs."}, "s02e10": {"q": "How do you stress that you have none at all, of a neuter thing?", "options": ["käs", "käis", "kei"], "why": "The emphatic neuter is «käis»."}}},
  "g21": {"title": "Demonstratives: dä, die, das", "summary": "Pointing at things. Same words as the articles, but said with stress.", "points": ["**dä** Maa (masculine) · **die** Frau (feminine) · **das** Chind (neuter) · **die** Chind (plural)", "Notice they are the articles de/d/s in their long, stressed form.", "To place them, add **da** (here) or **det** (there):", "**dä** Maa **da** = this man here · **die** Frau **det** = that woman over there", "**das** on its own means \"that\": \"Was isch **das**?\" · \"**Das** isch guet.\""], "tableHead": ["Gender", "Article", "Demonstrative"], "ex": {"g21e1": {"q": "___ Maa da isch min Nachbar. (this)", "why": "Masculine → dä."}, "g21e2": {"q": "___ Frau det schaffet mit mir.", "options": ["dä", "die", "das"], "why": "Feminine → die."}, "g21e3": {"q": "Was isch ___? (that)", "why": "\"das\" on its own = that."}, "g21e4": {"q": "What separates «de Vater» from «dee Vater»?", "options": ["Nothing, they are written the same", "The long e: the second one points", "The gender"], "why": "The masculine demonstrative is the article with a lengthened e. Schorn writes it «dä»."}, "g21e5": {"q": "How do you say «those children over there»?", "options": ["die Chind det", "das Chind det", "dä Chind det"], "why": "Plural → die, and \"det\" to mark the distance."}}},
  "s06": {"title": "Demonstratives with «daa» and «deet»", "summary": "From the class on 26/08. Pointing at things and saying whether they are near or far.", "points": ["**dä** (m) · **die** (f) · **das** (n) · **die** (pl)", "To place them, add **daa** (here) or **deet** (there), after the noun:", "Gfallt dir **das** T-Shirt **daa**? · Gfallt dir **die** Jagge, wo **deet** liit?", "They can stand alone, without the noun: «Gfallt dir die Brülle daa?» — «Ja, **die** gfallt mer.»", "With seasons and time spans they mark «this one» in contrast with the last one:", "De letscht Summer sim-mer id Berge, aber **dä** Summer möcht i as Meer.", "⚠️ The masculine is the tricky one: it is written like the article, and what separates them is **the length of the e**. To mark it, Holle writes **dee**: «**de** Vater» (the father) versus «**dee** Vater» (this father).", "Schorn writes it **dä**. Same sound; pick one spelling and stick to it.", "The feminine and neuter have no such problem: d Frau → **die** Frau · s Hus → **das** Hus."], "tableHead": ["Gender", "Article", "Demonstrative", "Example from class"], "ex": {"s06e1": {"q": "___ Bleistift (m) isch vo de Firma Caran d’Ache.", "why": "Masculine → dä."}, "s06e2": {"q": "___ Schoggi (f) isch vom Sprüngli.", "why": "Feminine → die."}, "s06e3": {"q": "___ Medikamänt isch vo de Novartis.", "options": ["Dä", "Die", "Das"], "why": "Medikamänt is neuter → das."}, "s06e4": {"q": "Gfallt dir ___ Jagge, wo deet liit? (feminine)", "why": "Jagge is feminine → die. And «deet» says it is the one over there."}, "s06e5": {"q": "Gfallt dir ___ Hämp daa?", "options": ["dä", "die", "das"], "why": "Hämp is neuter → das Hämp daa."}, "s06e6": {"q": "De letscht Winter bin i go Skifahre, aber ___ Winter gang i go Schneeschuehlaufe.", "why": "Winter is masculine → dä Winter (this winter)."}, "s06e7": {"q": "What does «deet» mean?", "options": ["here", "there", "now"], "why": "daa = here, deet = there."}}},
  "s09": {"title": "«e so-n-en» and «irgend en»", "summary": "From the class on 19/08. Such a…, some… or other. With the -n- that appears out of nowhere.", "points": ["**e so-n-en / e so-n-e / e so-n-es** = such a…, that kind of.", "Das isch **e so-n-en** stuure Bock! = What a stubborn man!", "Was **so-n-es** Chind nöd alles mit sich umeträit! = The things a child like that carries around!", "**irgend en / irgend e / irgend es** = some… or other.", "**Irgend en** Grund git s. = There must be some reason.", "Uf **irgend e** Art löst sich jedes Problem. = One way or another everything works out.", "Wänn Sie **irgend es** Aaliigge händ, lüütet Sie mir aa.", "The **-n-** in the middle is a linking sound: the dialect puts it between two vowels so they don’t clash. It does this everywhere: «wie-**n**-er», «chume-**n**-i»."], "ex": {"s09e1": {"q": "Das isch e so-n-___ stuure Bock (m)!", "options": ["en", "e", "es"], "why": "Bock is masculine → so-n-en."}, "s09e2": {"q": "Irgend ___ Grund (m) git s, warum d Steiböck striitet.", "why": "Masculine → irgend en."}, "s09e3": {"q": "Uf irgend ___ Art (f) löst sich jedes Problem.", "why": "Art is feminine → irgend e."}, "s09e4": {"q": "Wänn Sie irgend ___ Aaliigge (n) händ, lüütet Sie mir aa.", "options": ["en", "e", "es"], "why": "Aaliigge is neuter → irgend es."}, "s09e5": {"q": "Why is there an -n- in «e so-n-en»?", "options": ["It is part of the word", "It joins two vowels so they don’t clash", "It marks the plural"], "why": "It is the dialect’s linking sound, as in «wie-n-er» or «chume-n-i»."}, "s09e6": {"q": "Irgend ___ Chundin (f) hät aaglüütet.", "why": "Chundin is feminine → irgend e."}}},
  "s20": {"title": "öpper, öppis, öppe — and their opposites", "summary": "From class 7. Three words that look very alike and mean different things.", "points": ["**öpper** = someone (jemand) · **öppis** = something (etwas) · **öppe** = roughly, maybe (etwa)", "**öppedie** = now and then (dann und wann)", "Isch **öppen öpper** i s Huus ie choo? = Did someone come into the house?", "Ich hett gèèrn **öppis** Nöis. = I’d like something new.", "The opposites are words of their own; you don’t negate with nöd:", "**niemer** = nobody · **nüüt** = nothing · **niene** = nowhere", "Ich ha **niemer** gsee und **nie nüüt** ghöört. (the double negative here is normal)", "Mind the linking **-n-**: «öppe**n** öpper», as in «e so-n-en»."], "tableHead": ["Positive", "Means", "Opposite"], "ex": {"s20e1": {"q": "Isch ___ i s Huus ie choo? (someone)", "why": "öpper = jemand."}, "s20e2": {"q": "Ich hett gèèrn ___ Nöis. (something)", "why": "öppis = etwas."}, "s20e3": {"q": "Ich ha ___ gsee. (I saw nobody)", "options": ["nüüt", "niemer", "niene"], "why": "niemer = nobody. nüüt is «nothing» and niene «nowhere»."}, "s20e4": {"q": "What does «öppedie» mean?", "options": ["someone", "now and then", "nowhere"], "why": "öppedie = dann und wann."}, "s20e5": {"q": "___ mues doch miin Chugi sii! (somewhere)", "why": "näime / nöime = irgendwo."}, "s20e6": {"q": "There is an -n- in «öppen öpper». Why?", "options": ["It is part of the word", "A link between two vowels", "It marks the plural"], "why": "The same -n- as in «e so-n-en» or «wie-n-er»."}, "s20e7": {"q": "«Si hät nie nüüt gsäit» means…", "options": ["She never said anything", "She said something", "She always says things"], "why": "In dialect the double negative reinforces, it doesn’t cancel out."}}},
  "g22": {"title": "Noun plurals", "summary": "From the class on 09/09. The reliable clue isn’t the ending: it’s the article. In the plural it’s always «d».", "points": ["Whatever the gender, **the plural always takes d**: d Manne, d Fraue, d Chind.", "Four patterns:", "No change: s Chind → d **Chind** · s Zimmer → d **Zimmer**", "Umlaut only: de Tag → d **Täg** · de Vogel → d **Vögel**", "With -e: de Fründ → d **Fründe** · d Frau → d **Fraue**", "With -er and Umlaut (feminine and neuter): s Hus → d **Hüser** · s Buech → d **Büecher** · s Muul → d **Müüler** · s Chalb → d **Chälber**", "Here the dialect drifts from German: many masculines form the plural with an Umlaut alone, adding nothing.", "And diminutives never change: s Blüemli → d **Blüemli**.", "There is no rule that settles everything. When in doubt, ask in class: the book itself admits as much."], "tableHead": ["Singular", "Plural", "Pattern"], "ex": {"g22e1": {"q": "Plural of «s Huus» → d ___", "why": "-er with Umlaut: Hüüser."}, "g22e2": {"q": "Plural of «de Tag» → d ___", "why": "Umlaut only: Täg."}, "g22e3": {"q": "Plural of «s Chind»:", "options": ["d Chinder", "d Chind", "d Chinde"], "why": "No change. The article \"d\" is the only marker."}, "g22e4": {"q": "What is the most reliable clue that a noun is plural?", "options": ["The ending", "The article «d»", "The Umlaut"], "why": "Endings vary; the article \"d\" is always there."}, "g22e5": {"q": "Plural of «s Buech» → d ___", "why": "Büecher."}}},
  "h02": {"title": "Pronouns: er, sie, es", "summary": "From the class on 09/09. The pronoun comes from the noun’s gender, not from what the thing is.", "points": ["Article **de** → **er** · article **d** → **sie** · article **s** → **es**", "de Vater → **er** · d Mueter → **sie** · es Hus → **es**", "They sound the same as in German: nothing new to learn here.", "What catches you out is that gender outranks meaning:", "s Meitli (a girl) → **es** · s Grosi (grandma) → **es** · s Chind → **es**", "They are neuter because they are diminutives, and every diminutive is neuter.", "de Vogel → **er** · d Sunne → **sie** · s Velo → **es** · de Kafi → **er**"], "tableHead": ["Article", "Pronoun", "Example"], "ex": {"h02e1": {"q": "de Maa → ___", "why": "Article de → er."}, "h02e2": {"q": "d Tante → ___", "why": "Article d → sie."}, "h02e3": {"q": "s Velo → ___", "why": "Article s → es."}, "h02e4": {"q": "s Meitli (a girl) → which pronoun?", "options": ["sie", "es", "er"], "why": "Meitli is a diminutive, and diminutives are neuter: es. Even when it refers to a girl."}, "h02e5": {"q": "d Sunne → ?", "options": ["er", "sie", "es"], "why": "Sunne is feminine → sie."}, "h02e6": {"q": "de Öpfel → ___", "why": "Öpfel is masculine → er."}, "h02e7": {"q": "s Grosi (grandma) → ?", "options": ["sie, because she is a woman", "es, because the word is neuter"], "why": "Grammatical gender wins, not who the person is."}}},
  "g11": {"title": "Pronouns: dative and accusative", "summary": "The genitive doesn’t exist in dialect. You only need dative and accusative.", "points": ["Accusative (direct object): **mi** · **di** · **en** (him) · **sie** (her) · **üs** · **sie**", "Dative (indirect object): **mir** · **dir** · **em** (to him) · **ere** (to her) · **üs** · **ene**", "Chasch **mir** hälfe? (to me = dative, because \"hälfe\" takes the dative)", "Ich gseh **di** morn. (you = accusative)", "The German genitive is replaced by **vo** + dative: \"s Huus **vo mim** Brueder\"."], "tableHead": ["", "Accusative", "Dative"], "ex": {"g11e1": {"q": "Chasch ___ hälfe? (me)", "why": "\"hälfe\" takes the dative → mir."}, "g11e2": {"q": "Ich gseh ___ morn. (you)", "options": ["dir", "di", "du"], "why": "\"gseh\" takes the accusative → di."}, "g11e3": {"q": "Ich ha ___ s Buech gää. (to him)", "options": ["en", "em", "er"], "why": "The receiver = dative → em."}, "g11e4": {"q": "Chunsch du mit ___? (with us)", "why": "\"mit\" takes the dative → üs."}, "g11e5": {"q": "How do you say \"my brother’s house\"?", "options": ["s Huus vo mim Brueder", "s Huus mines Brueders", "mim Brueder s Huus"], "why": "No genitive: vo + dative."}}},
  "g23": {"title": "Address: du or Sie", "summary": "Getting this wrong is the mistake people notice most. Switzerland is stricter about it than Germany.", "points": ["**Sie** always takes the plural forms: Sie **händ**, Sie **chönd**, Sie **sind**.", "Greeting: **Grüezi** goes with Sie · **Hoi** and **Sali** go with du.", "Goodbye: **Uf Wiederluege** with Sie · **Tschüss** or **Ciao** with du.", "Use **Sie** with: strangers, shops, older people, clients, officialdom.", "Use **du** with: friends, family, children, and in many workplaces between colleagues.", "The **du** is always offered by the older or more senior person: \"Sölle mer **duze**?\"", "Rule of thumb: when in doubt, Sie. Moving from Sie to du is easy; the other way round is awkward."], "ex": {"g23e1": {"q": "At a supermarket till, how do you greet?", "options": ["Hoi!", "Grüezi!", "Sali!"], "why": "With strangers, Grüezi and Sie."}, "g23e2": {"q": "With Sie: ___ Sie hüt Ziit? (from haa)", "why": "Sie always takes the plural form: händ."}, "g23e3": {"q": "Which is correct with Sie?", "options": ["Chasch Sie mer hälfe?", "Chönd Sie mer hälfe?", "Cha Sie mer hälfe?"], "why": "Sie + chönd (plural)."}, "g23e4": {"q": "Who offers to switch to «du»?", "options": ["Anyone", "The older or more senior person", "Always the younger one"], "why": "In Switzerland this is quite strictly observed."}, "g23e5": {"q": "When in doubt, which do you use?", "options": ["du, it’s friendlier", "Sie", "Depends on the day"], "why": "Sie never offends; a misplaced du does."}}},
  "g01": {"title": "The verb sii (to be)", "summary": "The most important verb. In dialect the infinitive is \"sii\", not \"sein\".", "points": ["ich **bi** · du **bisch** · er/sie/es **isch**", "mir **sind** · ihr **sind** · sie **sind**", "All three plural forms are the same: always \"sind\".", "\"isch\" (not \"ist\") is the number one audible marker of Swiss German."], "tableHead": ["Züridütsch", "Hochdeutsch"], "ex": {"g01e1": {"q": "Ich ___ us Katalonie.", "options": ["bi", "bisch", "isch"], "why": "1st person singular: ich bi."}, "g01e2": {"q": "Du ___ hüt müed.", "options": ["bi", "bisch", "sind"], "why": "2nd person singular: du bisch (German -st becomes -sch)."}, "g01e3": {"q": "Er ___ mis Nachbar.", "options": ["bisch", "isch", "sind"], "why": "3rd person singular: er isch."}, "g01e4": {"q": "Mir ___ am Bahnhof.", "why": "The whole plural is \"sind\"."}, "g01e5": {"q": "Ihr ___ z spaat.", "why": "In dialect \"ihr sind\", not \"ihr seid\"."}, "g01e6": {"q": "How do you say \"he is friendly\"?", "options": ["Er isch fründlich.", "Er ist freundlich.", "Er bisch fründlich."], "why": "isch + fründlich (freundlich → fründlich)."}}},
  "h04": {"title": "werde: to become", "summary": "From the class on 16/09. The third basic verb, alongside sii and haa.", "points": ["ich **wird** · du **wirsch** · er/sie/es **wird** · mir/ihr/sie **werded**", "**sii** says what something is · **haa** says what you have · **werde** says what it turns into.", "Ich **wird** Arzt. = I’m going to be a doctor.", "De Himmel **wird** orange. = The sky is turning orange.", "Sie **wird** nie erwachse. = She’ll never grow up.", "⚠️ Careful: this «werde» is for becoming, **not** for the future. The future is the present plus a time word."], "tableHead": ["", "sii", "haa", "werde"], "ex": {"h04e1": {"q": "Ich ___ Arzt. (I’m going to be a doctor)", "why": "1st person: ich wird."}, "h04e2": {"q": "Du ___ es guets Chind. (you’re becoming)", "why": "2nd person: du wirsch."}, "h04e3": {"q": "De Himmel ___ orange.", "options": ["isch", "hät", "wird"], "why": "It is changing → werde."}, "h04e4": {"q": "Which verb for «Sie hat Pech»?", "options": ["Sie isch Päch.", "Sie hät Päch.", "Sie wird Päch."], "why": "Possession → haa."}, "h04e5": {"q": "Mir ___ alt. (we’re getting old)", "why": "Plural: werded."}, "h04e6": {"q": "How do you say «tomorrow I’ll work»?", "options": ["Ich wird morn schaffe.", "Morn schaffe ich."], "why": "«werde» doesn’t make the future: the present with «morn» is enough."}}},
  "h06": {"title": "The irregular verbs: all the forms", "summary": "From the class on 23/09. The 24 you have to know by heart. Learn them in chunks.", "points": ["The sheet groups them in sixes on purpose: **in portions**, not all at once.", "Group 1 — **sii, haa, gaa, tue, gèè, wele**", "Group 2 — **müese, chöne, möge, nèè, ässe, läse**", "Group 3 — **säge, trääge, choo, zie, träffe, wüsse**", "Group 4 — **sele, gsee, staa, laa, legge, ligge**", "The pattern that keeps repeating: **the plural always ends in -nd or -ed**, for all three persons.", "And watch the pairs people mix up: **legge** (to lay something down) versus **ligge** (to be lying down); **gèè** (to give) versus **gsee** (to see)."], "tableHead": ["", "gèè", "nèè", "ässe", "läse", "gsee"], "ex": {"h06e1": {"q": "Ich ___ dir es Buech. (from gèè)", "why": "ich gibe."}, "h06e2": {"q": "Er ___ de Zug. (from nèè)", "why": "er nimt."}, "h06e3": {"q": "Du ___ gèèrn d Ziitig. (from läse)", "options": ["lisisch", "läsed", "list"], "why": "2nd person: du lisisch."}, "h06e4": {"q": "What is the difference between «legge» and «ligge»?", "options": ["None", "legge = to lay something down · ligge = to be lying down", "legge is the plural"], "why": "legge/läit puts something down · ligge/liit is lying there."}, "h06e5": {"q": "Mir ___ z Mittag. (from ässe)", "why": "Plural: ässed."}, "h06e6": {"q": "Ich ___ gaar nüüt. (I can’t see a thing)", "options": ["gibe", "gsee", "gib"], "why": "gsee = to see. Don’t mix it up with gèè."}, "h06e7": {"q": "How does the plural always end?", "options": ["in -e", "in -nd or -ed", "in -sch"], "why": "gänd, nämed, ässed, gseend, stönd, lönd…"}}},
  "g02": {"title": "The verb haa (to have)", "summary": "\"haben\" becomes \"haa\". The plural ends in -nd, like almost everything.", "points": ["ich **ha** · du **hesch** · er/sie/es **het**", "mir **händ** · ihr **händ** · sie **händ**", "It also builds the past: \"ich **ha** gässe\" (I have eaten)."], "tableHead": ["Züridütsch", "Hochdeutsch"], "ex": {"g02e1": {"q": "Ich ___ kei Ziit.", "options": ["ha", "hesch", "het"], "why": "ich ha."}, "g02e2": {"q": "Du ___ es schöns Huus.", "options": ["ha", "hesch", "händ"], "why": "du hesch."}, "g02e3": {"q": "Sie ___ zwei Chind.", "why": "Plural: händ."}, "g02e4": {"q": "Er ___ Hunger.", "why": "3rd person singular: het."}, "g02e5": {"q": "How do you say \"we have a meeting\"?", "options": ["Mir händ e Sitzig.", "Mir haben eine Sitzung.", "Mir het e Sitzig."], "why": "mir händ + e Sitzig (die Sitzung → d Sitzig)."}, "g02e6": {"q": "Ihr ___ rächt.", "why": "ihr händ = ihr habt."}}},
  "g03": {"title": "Present tense of regular verbs", "summary": "One single pattern for nearly every verb. Far easier than standard German.", "points": ["The infinitive ends in **-e** (not -en): mach**e**, lehr**e**, schaff**e**.", "ich mach**e** · du mach**sch** · er mach**t**", "mir mach**ed** · ihr mach**ed** · sie mach**ed**", "All three plural persons are ALWAYS the same. Remember: **-ed**.", "The German -st becomes -sch everywhere: du schaff**sch**, du lehr**sch**.", "⚠️ Exception from the class on 16/09: if the stem ends in **z** or **s**, the second person adds an **i**, because otherwise you couldn’t pronounce it.", "tanze → du tanz**isch** · heisse → du heiss**isch** · reise → du reis**isch** · putze → du putz**isch** · küsse → du küss**isch** · motze → du motz**isch**"], "tableHead": ["Person", "mache (to do)", "schaffe (to work)"], "ex": {"g03e1": {"q": "Du ___ (schaffe) z Züri.", "why": "2nd sing. → -sch: schaffsch."}, "g03e2": {"q": "Mir ___ (lehre) Schwiizerdütsch.", "why": "Plural → -ed: lehred."}, "g03e3": {"q": "Was ___ ihr am Wuchenänd?", "options": ["machsch", "mached", "macht"], "why": "\"ihr\" is plural → mached."}, "g03e4": {"q": "If she works a lot: \"Sie ___ vil.\"", "options": ["schaffsch", "schafft", "schaffed"], "why": "\"sie\" singular (she) → schafft."}, "g03e5": {"q": "Ich ___ (warte) uf de Bus.", "why": "1st sing. = the infinitive: warte."}, "g03e6": {"q": "Which is the correct dialect infinitive?", "options": ["lernen", "lehre", "lehren"], "why": "Infinitives drop the final -n: lernen → lehre."}, "g03e7": {"q": "Du ___ (tanze) sehr guet.", "why": "The stem ends in z → du tanzisch, not «tanzsch»."}, "g03e8": {"q": "What is the 2nd person of «heisse»?", "options": ["heissch", "heissisch", "heisst"], "why": "Stem ending in s → an i is added."}, "g03e9": {"q": "Why «putzisch» and not «putzsch»?", "options": ["Because it is irregular", "Because «tzsch» can’t be pronounced", "Because it is plural"], "why": "The i is there so you can say it."}}},
  "g07": {"title": "Modal verbs: chöne, wölle, müese", "summary": "The three you’ll use every day. The second verb goes to the infinitive, at the end.", "points": ["**chöne** (can): ich cha · du chasch · er cha · mir chönd", "**wölle** (to want): ich wott · du wottsch · er wott · mir wänd", "**müese** (to have to): ich mues · du muesch · er mues · mir müend", "Structure: conjugated modal + ... + infinitive **at the end**.", "Ich **cha** hüt nöd **cho**. · Ich **wott** es Bier **trinke**."], "tableHead": ["", "chöne", "wölle", "müese"], "ex": {"g07e1": {"q": "Ich ___ hüt nöd cho. (can)", "why": "ich cha."}, "g07e2": {"q": "Du ___ es Bier? (want)", "why": "du wottsch."}, "g07e3": {"q": "Mir ___ jetzt gaa. (have to)", "options": ["mues", "muesch", "müend"], "why": "Plural → müend."}, "g07e4": {"q": "Where does the infinitive go in \"Ich cha ___ ___\"?", "options": ["Right after the modal", "At the end of the sentence", "At the beginning"], "why": "The infinitive always closes the sentence: \"Ich cha hüt nöd cho.\""}, "g07e5": {"q": "Translate: \"I want to learn Swiss German.\"", "options": ["Ich wott Schwiizerdütsch lehre.", "Ich lehre wott Schwiizerdütsch.", "Ich wott lehre Schwiizerdütsch."], "why": "Modal in second position, infinitive at the end."}, "g07e6": {"q": "Er ___ am achti da sii. (has to)", "why": "er mues."}, "g07e7": {"q": "Ich ___ hüt lenger blibe. (I’m allowed)", "why": "dörfe → ich dörf."}, "g07e8": {"q": "«Ich cha schwüme» versus «Ich dörf schwüme»:", "options": ["They mean the same", "The first is being able to, the second being allowed to", "The second is past tense"], "why": "chöne = ability · dörfe = permission."}, "g07e9": {"q": "Ich ___ nöd uufstaa. (I don’t feel like it)", "why": "möge → ich mag."}}},
  "g16": {"title": "Separable verbs", "summary": "Verbs that split apart: the prefix goes to the end of the sentence.", "points": ["**uufstah** (to get up) → Ich **stande** am sibni **uf**.", "**aafange** (to start) → De Film **fangt** am achti **aa**.", "**iichaufe** (to shop) → Ich **chaufe** am Samschtig **ii**.", "**mitcho** (to come along) → **Chunsch** du **mit**?", "In the perfect the prefix sticks back on, before the ge-: uf**g**stande, aa**g**fange.", "Ich bi am sibni **uufgstande**. · De Film het **aagfange**."], "ex": {"g16e1": {"q": "Which is correct? (uufstah, at seven)", "options": ["Ich uufstande am sibni.", "Ich stande am sibni uf.", "Ich stande uf am sibni."], "why": "The prefix \"uf\" closes the sentence."}, "g16e2": {"q": "De Kurs fangt am nüüni ___. (aafange)", "why": "The separated prefix goes at the end: fangt … aa."}, "g16e3": {"q": "How do you ask «are you coming with us?»", "options": ["Mitchunsch du?", "Chunsch du mit?", "Du mitchunsch?"], "why": "Verb first (question), prefix at the end."}, "g16e4": {"q": "Past of «Ich stande uf»:", "options": ["Ich bi uufgstande.", "Ich ha uufgstande.", "Ich bi gstande uf."], "why": "Verb of motion/change of state → sii. And the prefix sticks back on: uufgstande."}, "g16e5": {"q": "Tell someone to stop: Hör ___! (ufhöre)", "why": "Hör uf! = That’s enough!"}}},
  "s08": {"title": "Swiss verbs and false friends", "summary": "From the class on 26/08. Verbs that exist in German but mean something else. This is where everyone trips up.", "points": ["**lauffe** = to walk (NOT to run). «Du muesch mee **lauffe**» = you need to walk more.", "To run: **räne** or **springe**. To jump: **gumpe**.", "**schaffe** = to work (NOT to create). «Er **schaffet** nüme vil.»", "To create, to make: **mache**. «Das hät en Künschtler **gmacht**.»", "**schmöcke** = to smell (NOT to taste). «**Schmöcksch** dë Gschtank?»", "To taste: **tunke**. «Wie **tunkt** s di?» = how does it taste to you?", "**hebe** = to hold (NOT to lift). «**Heb** emaal de Hamer!»", "To lift: **lupfe**. «**Lupf** emaal dë Choorb!»", "And four more you’ll hear daily: **aalüüte** (to phone), **gspüüre** (to feel), **trüle** (to turn), **lange** (to be enough).", "«Jetz **langet** s aber!» = that’s enough!"], "tableHead": ["Means", "Dialect", "The trap"], "ex": {"s08e1": {"q": "«Du muesch mee lauffe» means…", "options": ["you need to run more", "you need to walk more", "you need to work more"], "why": "lauffe = to walk. The most treacherous false friend of all."}, "s08e2": {"q": "To say «to run» in dialect: ___ (or springe)", "why": "räne or springe."}, "s08e3": {"q": "«Schmöcksch das?» asks whether you…", "options": ["can taste it", "can smell it", "can hear it"], "why": "schmöcke = to smell. For taste it’s «tunke»."}, "s08e4": {"q": "Your colleague says «Heb emaal de Hamer!». What do they want?", "options": ["You to lift the hammer", "You to hold the hammer", "You to hand them the hammer"], "why": "hebe = to hold. To lift would be «Lupf de Hamer!»."}, "s08e5": {"q": "«Er ___ nüme vil» = he doesn’t work much any more.", "why": "schaffe = to work, 3rd person schaffet."}, "s08e6": {"q": "«Wie tunkt s di?» asks…", "options": ["how it tastes to you", "how you feel", "what you think"], "why": "tunke = to taste."}, "s08e7": {"q": "«Jetz langet s aber!» means…", "options": ["It’s arriving!", "That’s enough!", "It’s long!"], "why": "lange = to be enough. Said crossly."}, "s08e8": {"q": "To say «to phone»: ___ (or telifoniere)", "why": "«Ich han ere wele aalüüte.»"}, "s08e9": {"q": "An artist made a work. Which verb?", "options": ["Das hät en Künschtler gschafft.", "Das hät en Künschtler gmacht."], "why": "mache = to create. schaffe is to work."}}},
  "h01": {"title": "Swiss expressions II: amigs, ämel, öppedie", "summary": "From the class on 02/09. The nuances that don’t translate but change everything.", "points": ["**amigs** = each time, usually. «Si gaat **amigs** uf Züri go poschte.»", "**ämel** = at least, in any case. «Ich han **ämel** nüüt ghöört.»", "**efängs** = for now. «Mir gönd **efängs**.»", "**ächt** and **mäini** = probably…, I think so. «Sind s **ächt** verräist? **Mäini** scho.»", "The **ö-** family: **öpper** (someone) · **öppis** (something) · **öppe** (roughly) · **öppen emaal** (now and then) · **öppedie** (sometimes).", "And four that sound alike but aren’t: **abenand** (broken in two) · **anenand** (non-stop) · **umenand** (back and forth) · **allpott** (over and over).", "**momoll** is the reinforced «doch»: «Äch, chunsch nöd mit? **Momoll**!»"], "tableHead": ["Dialect", "Means", "Example from class"], "ex": {"h01e1": {"q": "Si gaat ___ uf Züri go poschte. (each time)", "why": "amigs = jeweils."}, "h01e2": {"q": "Ich han ___ nüüt ghöört. (at least)", "why": "ämel = jedenfalls."}, "h01e3": {"q": "Which one means «roughly»?", "options": ["öpper", "öppis", "öppe"], "why": "öpper = someone · öppis = something · öppe = roughly."}, "h01e4": {"q": "«Das schöön Glaas isch ___» = the glass has broken.", "options": ["anenand", "abenand", "umenand"], "why": "abenand = entzwei, snapped in two."}, "h01e5": {"q": "«Föif Stund ___ hät si gspilt» = she played for five hours…", "options": ["straight", "back and forth", "on and off"], "why": "anenand = ununterbrochen, non-stop."}, "h01e6": {"q": "Sind s ächt verräist? — ___ scho. (I think so)", "why": "From «meine ich»."}, "h01e7": {"q": "Someone asks «Chunsch nöd mit?» and you do want to come. What do you say?", "options": ["Nei!", "Momoll!", "Ämel!"], "why": "momoll = yes I am, contradicting the negative question."}, "h01e8": {"q": "S rägnet ___ und glii wider. (over and over)", "why": "allpott = immer wieder."}}},
  "s21": {"title": "Which verbs split and which don’t", "summary": "From class 7. The prefix goes to the end… but only for some. The table from «Vor em Renoviere».", "points": ["They split: **uufruume** → ich ruume **uuf** · **furtrüere** → ich rüere **furt**", "They do NOT split: **versoorge** → ich versoorge · **trääge** → ich trääge", "The clue: if the prefix is a word with a meaning of its own (**uuf**, **furt**, **aa**, **ab**, **mit**, **ue**), it splits.", "If it is an unstressed prefix that means nothing alone (**ver-**, **be-**, **ge-**, **er-**), it doesn’t.", "S Rägi **ruumt** d Chuchi **uuf**. · S Rägi **versoorget** s Gschiir.", "Mind trääge, which changes its vowel: ich trääge, du **träisch**, er **träit**, mir trääged."], "tableHead": ["", "uufruume (sep.)", "furtrüere (sep.)", "versoorge", "trääge"], "ex": {"s21e1": {"q": "S Rägi ___ d Chuchi uuf. (uufruume)", "why": "It splits: ruumt … uuf."}, "s21e2": {"q": "Which is correct with furtrüere?", "options": ["S Rägi furtrüert di Schue.", "S Rägi rüert di Schue furt.", "S Rägi rüert furt di Schue."], "why": "The prefix «furt» closes the sentence."}, "s21e3": {"q": "S Rägi ___ s Gschiir. (versoorge)", "why": "ver- never splits: versoorget."}, "s21e4": {"q": "De Hans ___ e schwèèri Büecherchischte. (trääge)", "why": "3rd person: träit, with a vowel change."}, "s21e5": {"q": "How do you know whether a verb splits?", "options": ["By the number of syllables", "If the prefix means something on its own", "If it ends in -e"], "why": "uuf, furt, aa, ab, mit are words with their own meaning and they split. ver-, be-, ge-, er- don’t."}, "s21e6": {"q": "___ du d Winden uuf, Rägi? (uufruume)", "why": "2nd person: ruumsch … uuf."}, "s21e7": {"q": "Mer ___ aber ja nöd ales furt! (furtrüere, we)", "options": ["rüere", "rüert", "rüered"], "why": "Plural: rüered … furt."}}},
  "h08": {"title": "Swiss expressions III: home and chores", "summary": "From the class on 23/09. The household vocabulary that looks nothing like German.", "points": ["The five meals of the day: **Zmorge** · **Znüüni** · **Zmittaag** · **Zvieri** · **Znacht**. And the verb: **zmörgele**.", "Things around the house: **d Gufe** (pin) · **s Chlüppli** (clothes peg) · **de Finke** (slipper) · **de Lumpe** (cloth) · **d Schooss** (apron)", "Chores: **büeze** (to sew) · **lisme** (to knit) · **glette** (to iron) · **butze** (to clean) · **zügle** (to move house)", "Inside the house: **de Gang** (hallway) · **d Stäge** (stairs) · **d Tüürfale** (door handle) · **s Chämi** (fireplace) · **d Stube** (living room)", "Quantities: **e Hampfle** (a handful) · **es Stuck** (a piece) · **es bitzeli** (a little bit) · **es birebitzeli** (even less)", "«Legged d Finken aa!» is what you’ll be told on entering any Swiss home."], "ex": {"h08e1": {"q": "«Legged d Finken aa!» asks you to…", "options": ["climb the stairs", "put it in your mouth", "put on the slippers"], "why": "de Finke = Hausschuh. You’ll hear it in every house."}, "h08e2": {"q": "Si mues d Hämper ___. (to iron)", "why": "glette = bügeln."}, "h08e3": {"q": "What is a «Züglete»?", "options": ["a house move", "a staircase", "a meal"], "why": "From zügle = umziehen."}, "h08e4": {"q": "Pass uf d ___ uuf! (the stairs)", "why": "d Stäge = die Treppe."}, "h08e5": {"q": "Put the meals of the day in order:", "options": ["Zmorge · Znüüni · Zmittaag · Zvieri · Znacht", "Znüüni · Zmorge · Zvieri · Zmittaag · Znacht"], "why": "Znüüni is the nine o’clock one and Zvieri the four o’clock one: the names say so."}, "h08e6": {"q": "Gisch mer es ___ Chriesi? (a handful)", "why": "e Hampfle, diminutive es Hämpfeli."}, "h08e7": {"q": "«es birebitzeli» is…", "options": ["more than es bitzeli", "even less than es bitzeli"], "why": "It is the diminutive of the diminutive."}}},
  "s22": {"title": "The verb sheet — intensive practice", "summary": "The whole «Typisch schweizerische Ausdrücke» sheet as exercises. It’s the sheet you keep going back to: here you can drill it until it comes out by itself.", "points": ["The four false friends that catch people out most:", "**lauffe** = to walk (not to run) · **schaffe** = to work (not to create)", "**schmöcke** = to smell (not to taste) · **hebe** = to hold (not to lift)", "And the pairs you have to learn together:", "to run **räne / springe** · to jump **gumpe** · to taste **tunke** · to lift **lupfe**", "to throw **rüere / furtrüere** · to cry **briegge** · to shriek **göisse** · to wreck **schliisse, verheie**", "The example sentences are worth learning whole: those are the ones you’ll hear."], "ex": {"s22e1": {"q": "Du muesch mee ___. (to walk)", "why": "lauffe = to walk. False friend number one."}, "s22e2": {"q": "Er cha na guet ___. (to run)", "why": "räne or springe = to run."}, "s22e3": {"q": "«S Mäitli tuet sälli gumpe» means the girl…", "options": ["runs", "jumps", "cries"], "why": "gumpe = to jump."}, "s22e4": {"q": "Er ___ nüme vil. (to work, 3rd person)", "why": "schaffe = to work."}, "s22e5": {"q": "Das hät en Künschtler ___.", "options": ["gschafft", "gmacht", "übercho"], "why": "To create a work, mache. schaffe is to work."}, "s22e6": {"q": "Wèr hät das ___? (to receive)", "why": "überchoo = bekommen."}, "s22e7": {"q": "«Wie tunkt s di?» asks…", "options": ["how it tastes to you", "how you feel", "what you think"], "why": "tunke = to taste."}, "s22e8": {"q": "___ du dèè Gschtank? (to smell it)", "why": "schmöcke = to smell."}, "s22e9": {"q": "«Ich gseene gaar nüüt» means…", "options": ["I hear nothing", "I can’t see a thing", "I understand nothing"], "why": "gsee = to see. «gaar nüüt» = absolutely nothing."}, "s22e10": {"q": "Lueg emaal dèè Röiel ___! (look at it)", "why": "aaluege splits: lueg … aa."}, "s22e11": {"q": "«Das ghöört dir» means…", "options": ["You can hear it", "That belongs to you", "They’re telling you"], "why": "ghööre = to hear AND to belong. Here, to belong."}, "s22e12": {"q": "Luege, ___, lauffe! (the road-safety motto)", "why": "Look, listen, walk."}, "s22e13": {"q": "Häsch nie gleert ___? (to obey)", "why": "folge = gehorchen."}, "s22e14": {"q": "You want someone to lift a basket. What do you say?", "options": ["Heb emaal dèè Choorb!", "Lupf emaal dèè Choorb!", "Trääg emaal dèè Choorb!"], "why": "lupfe = to lift. hebe would be to hold it."}, "s22e15": {"q": "And if you want them to hold it?", "options": ["Lupf en!", "Heb en!", "Rüer en furt!"], "why": "hebe = halten."}, "s22e16": {"q": "Das ___ i nüme lenger. (to keep)", "why": "bhalte = behalten."}, "s22e17": {"q": "___ äntli diini Büecher! (put away)", "why": "versoorge = wegräumen."}, "s22e18": {"q": "«De Moond schwiinet» means the moon…", "options": ["is shining", "is waning", "is rising"], "why": "schwiine = schwinden, to wane."}, "s22e19": {"q": "Chasch diin Chopf echli ___? (to turn)", "why": "trüle = drehen."}, "s22e20": {"q": "Ich han ere äigetli wele ___. (to phone)", "why": "aalüüte = anrufen."}, "s22e21": {"q": "«Für das langet d Ziit nüme» means…", "options": ["There isn’t enough time any more", "Time is long", "Time passes"], "why": "lange = to be enough."}, "s22e22": {"q": "«Jetz langet s aber!» is said when…", "options": ["Someone arrives", "That’s enough", "Not much is left"], "why": "Said crossly. That’s enough."}, "s22e23": {"q": "Broot ___ me nöd furt! (to throw)", "why": "rüere = werfen. You don’t throw bread away."}, "s22e24": {"q": "«Es mues schüüli briegge» means the child…", "options": ["shouts a lot", "cries a lot", "laughs a lot"], "why": "briegge = to cry. schüüli = terribly."}, "s22e25": {"q": "Nu d Mäitli ___ immer. (to shriek, plural)", "why": "göisse = kreischen."}, "s22e26": {"q": "D Siite vom Nooteheft ___. (to turn)", "why": "cheere / umcheere = wenden."}, "s22e27": {"q": "Wèr hät das ___? (to wreck)", "options": ["gschlisse", "gschaffet", "gspöizt"], "why": "schliisse (or verheie) = to destroy."}, "s22e28": {"q": "Die zwoo Tüüre ___ scho lang. (to creak)", "why": "giire = knarren. Plural: giired."}, "s22e29": {"q": "«Dèè spöizt bim Rede» means he…", "options": ["shouts when talking", "spits when talking", "stutters"], "why": "spöize = spucken."}, "s22e30": {"q": "«So fiini Haar hät das Mäiteli.» Here «fiin» means…", "options": ["tasty", "fine, thin", "clean"], "why": "«fäin» is for food; «fiin» for everything else."}, "s22e31": {"q": "Bim Wüme mues me si ___. (to bend down)", "why": "pucke = sich bücken."}, "s22e32": {"q": "Stürchle nöd über d ___! (the cobblestones)", "why": "Bsetzi = the paving, Bsetzistäi = the stones."}, "s22e33": {"q": "«De Güselchübel isch porzevole» means the bin…", "options": ["is empty", "is full to the brim", "smells"], "why": "porzevole = randvoll."}, "s22e34": {"q": "Muesch d Händsche ___! (to put on)", "why": "aalegge = anziehen."}, "s22e35": {"q": "Zie äntli dèè Wulepuli ___! (to take off)", "why": "abzie splits: zie … ab."}, "s22e36": {"q": "«Mer gönd gschiider ufs Trottoir» means…", "options": ["Let’s go faster along the pavement", "We’d better go on the pavement", "We always go on the pavement"], "why": "gschiider = we’d better…"}, "s22e37": {"q": "Settsch di halt emaal ___. (to comb your hair)", "why": "strèèle, from de Strèèl (the comb)."}, "s22e38": {"q": "Which of these does NOT mean to run?", "options": ["räne", "springe", "lauffe"], "why": "lauffe is to walk. Remember it."}}},
  "g24": {"title": "Gang go & chum cho", "summary": "A construction German doesn’t have and you’ll hear every day. Going to do something.", "points": ["To say \"to go and do something\" you put **go** in the middle:", "**gaa** + **go** + infinitive → Ich **gang go poschte**. = I’m going shopping.", "Ich **gang go schlafe**. = I’m off to bed. · Mir **gönd go ässe**. = We’re going to eat.", "With the verb to come, the particle is **cho**:", "**cho** + **cho** + infinitive → **Chunsch cho ässe?** = Are you coming to eat?", "Er **chunt cho luege**. = He’s coming to watch.", "The particle doesn’t translate and **can’t be left out**. In German it would just be \"Ich gehe einkaufen\".", "It is one of the clearest signs that you’re speaking dialect and not German."], "tableHead": ["Züridütsch", "Hochdeutsch", "English"], "ex": {"g24e1": {"q": "Ich gang ___ poschte. (the particle)", "why": "With gaa, always \"go\"."}, "g24e2": {"q": "Chunsch ___ ässe? (the particle)", "why": "With cho, the particle is \"cho\"."}, "g24e3": {"q": "Which is correct?", "options": ["Mir gönd ässe.", "Mir gönd go ässe.", "Mir gönd cho ässe."], "why": "gaa needs \"go\". Without the particle it sounds German."}, "g24e4": {"q": "What does «go» mean here?", "options": ["Nothing on its own, it’s obligatory", "«already»", "«towards»"], "why": "It doesn’t translate; it’s part of the construction."}, "g24e5": {"q": "Translate: «He’s coming to help.»", "options": ["Er chunt hälfe.", "Er chunt cho hälfe.", "Er gaht go hälfe."], "why": "cho + cho + infinitive."}}},
  "g09": {"title": "Word order", "summary": "Same as German: the conjugated verb goes in second position. Always.", "points": ["Statement: **Ich gang** hüt i d Stadt.", "If you start with something else, the verb is still second: **Hüt gang ich** i d Stadt.", "Yes/no question: the verb goes FIRST — **Gasch** du hüt i d Stadt?", "W- question: W- + verb + subject — **Wo gasch** du hii?", "With \"wil\" (because) the verb goes to the END: Ich blibe deheim, **wil** ich müed **bi**."], "ex": {"g09e1": {"q": "Which is correct?", "options": ["Hüt ich gang i d Stadt.", "Hüt gang ich i d Stadt.", "Hüt i d Stadt gang ich."], "why": "The verb must be the second element: Hüt (1) gang (2) ich."}, "g09e2": {"q": "How do you ask \"are you coming tomorrow?\"", "options": ["Du chunsch morn?", "Chunsch du morn?", "Morn du chunsch?"], "why": "Yes/no question → verb first."}, "g09e3": {"q": "Put in order: [wo] [du] [wohnsch] →  ___ wohnsch du?", "why": "W- + verb + subject: Wo wohnsch du?"}, "g09e4": {"q": "Which is correct with \"wil\"?", "options": ["Ich chume nöd, wil ich bi chrank.", "Ich chume nöd, wil ich chrank bi.", "Ich chume nöd, wil bi ich chrank."], "why": "After \"wil\" the conjugated verb goes at the end."}, "g09e5": {"q": "Translate: \"Tomorrow I work in Zurich.\"", "options": ["Morn ich schaffe z Züri.", "Morn schaffe ich z Züri.", "Ich morn schaffe z Züri."], "why": "Verb in second position."}, "g09e6": {"q": "Ask the time: ___ spaat isch es?", "why": "Wie spaat isch es? = What time is it?"}}},
  "h05": {"title": "Questions: the verb before the subject", "summary": "From the class on 16/09. To ask, flip the order. And the verb changes a little.", "points": ["Statement: **S Wätter isch** schön. → Question: **Isch s Wätter** schön?", "**Du bisch** da. → **Bisch du** da? · **Mir sind** gross. → **Sind mir** gross?", "With «ich» the verb often gets back an -n that the normal form has lost:", "ich bi → **bin i**? · ich ha → **han i**? · ich gaane → **gaan i**? · ich chume → **chum i**?", "ich gsee → **gseen i**? · ich staane → **staan i**? · ich laane → **laan i**?", "And there is a form for suggesting things, by fusing the verb with «mer» (= mir):", "**simer** (let’s be) · **hämer** (let’s have) · **gömer** (let’s go) · **chömer** (let’s come) · **ässed mer** (let’s eat)"], "tableHead": ["Statement", "Question"], "ex": {"h05e1": {"q": "Turn into a question: «Sie isch schnäll.»", "options": ["Sie isch schnäll?", "Isch sie schnäll?", "Schnäll isch sie?"], "why": "Verb before the subject."}, "h05e2": {"q": "Ich ha Ziit. → ___ i Ziit?", "why": "With ich, «ha» gets the -n back: han i?"}, "h05e3": {"q": "Ich bi lustig. → ___ i lustig?", "why": "bin i?"}, "h05e4": {"q": "Turn into a question: «Du bisch z spaat.»", "options": ["Bisch du z spaat?", "Du bisch z spaat?", "Z spaat bisch du?"], "why": "Verb first."}, "h05e5": {"q": "What does «Gömer» mean?", "options": ["Shall we go?", "I go", "They went"], "why": "It is gaa + mer: a suggestion, «let’s go»."}, "h05e6": {"q": "Suggest eating together: ___ mer! (from ässe)", "why": "ässed mer = let’s eat."}}},
  "g25": {"title": "Ordinal numbers and dates", "summary": "First, second, third… and how to say a date.", "points": ["**erschte · zweite · dritte · vierte · füfte · sächste · sibte · achte · nüünte · zähnte**", "From 20 on you add **-schte**: zwänzg → **zwänzgschte**", "Dates with **am** + ordinal: **am erschte Mai** · **am zwölfte Februar**", "Floors with **im**: **im dritte Stock** = on the third floor", "Remember cardinals run the other way round: **einezwänzg** = 21 (one-and-twenty)."], "tableHead": ["Number", "Cardinal", "Ordinal"], "ex": {"g25e1": {"q": "Ordinal of «eis» → ___", "why": "erschte, like \"erste\" in German."}, "g25e2": {"q": "How do you say «the first of May»?", "options": ["am eis Mai", "am erschte Mai", "de eis Mai"], "why": "am + ordinal."}, "g25e3": {"q": "Ordinal of «drü» → ___", "why": "dritte."}, "g25e4": {"q": "What does «einezwänzg» mean?", "options": ["12", "21", "20"], "why": "Unit first, then the ten: one-and-twenty = 21."}, "g25e5": {"q": "How do you say «on the third floor»?", "options": ["am dritte Stock", "im dritte Stock", "uf dritte Stock"], "why": "Floors with \"im\"."}}},
  "g20": {"title": "Adjectives before the noun", "summary": "The endings -e / -i / -s. Here the dialect does NOT behave like German.", "points": ["After sii they take nothing: \"De Maa isch **alt**.\" · \"D Frau isch **alt**.\"", "Before a noun with an indefinite article, they do:", "masculine: en **alte** Maa · feminine: e **alti** Frau · neuter: es **alts** Chind", "plural: **alti** Chind", "The feminine **-i** is the one that sounds most Swiss (German: eine alt**e** Frau).", "The neuter takes **-s**, not -es: es guet**s** Buech."], "tableHead": ["Gender", "Dialect", "Hochdeutsch"], "ex": {"g20e1": {"q": "Es isch e ___ Frau. (nätt)", "why": "Feminine indefinite → -i."}, "g20e2": {"q": "Das isch es ___ Buech.", "options": ["guete", "gueti", "guets"], "why": "Neuter → -s: es guets Buech."}, "g20e3": {"q": "Ich ha en ___ Fründ.", "options": ["guete", "gueti", "guets"], "why": "Masculine → -e: en guete Fründ."}, "g20e4": {"q": "After the verb it takes no ending: D Frau isch ___. (alt)", "why": "Predicative use → bare adjective."}, "g20e5": {"q": "Which ending gives away most that you’re speaking dialect, not German?", "options": ["The masculine -e", "The feminine -i", "Neither"], "why": "German says \"eine gute Frau\"; the dialect, \"e gueti Frau\"."}}},
  "s03": {"title": "Adjectives with the indefinite article", "summary": "From the class on 19/08. The adjective ending rhymes with the article’s. It’s mechanical.", "points": ["masculine: **en** guet**e** Vorschlag", "feminine: **e** guet**i** Lösig", "neuter: **es** guet**s** Aagebot", "The trick: look at how the article ends and put the same letter on the adjective.", "**en** … **-e** · **e** … **-i** · **es** … **-s**", "It works the same whether the adjective ends in a consonant or a vowel:", "**en** intressant**e** Bruef · **e** intelligänt**i** Frag · **es** international**s** Labor", "After the verb the adjective is bare: «De Vorschlag isch **guet**.»"], "tableHead": ["Gender", "Article", "Adjective", "Example"], "ex": {"s03e1": {"q": "Ending: en guet___ Vorschlag (m)", "why": "Masculine: en … -e."}, "s03e2": {"q": "Ending: e guet___ Lösig (f)", "why": "Feminine: e … -i."}, "s03e3": {"q": "Ending: es guet___ Aagebot (n)", "why": "Neuter: es … -s."}, "s03e4": {"q": "How do you say «an important client»?", "options": ["e wichtigi Chund", "en wichtige Chund", "es wichtigs Chund"], "why": "Chund is masculine → en wichtige Chund."}, "s03e5": {"q": "How do you say «an expensive restaurant»?", "options": ["en tüüre Reschtaurant", "e tüüri Reschtaurant", "es tüürs Reschtaurant"], "why": "Reschtaurant is neuter → es tüürs."}, "s03e6": {"q": "e intelligänt___ Antwort (f) gäh", "why": "Feminine → -i, also with adjectives ending in a consonant."}, "s03e7": {"q": "How do you say «an experienced doctor (f)»?", "options": ["e erfahreni Ärztin", "en erfahrene Ärztin", "es erfahrens Ärztin"], "why": "Ärztin is feminine → e … -i."}, "s03e8": {"q": "es alt___ Buech (n) läse", "why": "Neuter → -s: es alts Buech."}, "s03e9": {"q": "And after the verb? «De Chueche isch ___.»", "options": ["feine", "feini", "fein"], "why": "In predicative position the adjective takes nothing."}, "s03e10": {"q": "en einzeln___ Socke (m)", "why": "Socke is masculine in dialect → en einzelne Socke."}}},
  "g26": {"title": "Possessives: min, mini, mis", "summary": "The same three endings as the adjectives: -n / -i / -s.", "points": ["masculine **min** Vatter · feminine **mini** Mueter · neuter **mis** Chind · plural **mini** Chind", "With you: **din** Vatter · **dini** Mueter · **dis** Chind · **dini** Chind", "His: **sin** / **sini** / **sis** · Ours: **üse** / **üsi** / **üses**", "Notice the pattern: the feminine and the plural take **-i**, just like the adjectives (e guet**i** Frau).", "Remember there is no genitive: \"my brother’s house\" = s Huus **vo mim** Brueder."], "tableHead": ["", "masculine", "feminine", "neuter"], "ex": {"g26e1": {"q": "___ Mueter chunt morn. (my)", "why": "Feminine → -i: mini Mueter."}, "g26e2": {"q": "___ Chind isch chrank. (my)", "options": ["min", "mini", "mis"], "why": "Neuter → -s: mis Chind."}, "g26e3": {"q": "Wo isch ___ Velo? (your bike, s Velo is neuter)", "why": "Neuter → dis."}, "g26e4": {"q": "How do you say «my sister’s house»?", "options": ["mini Schwöschter s Huus", "s Huus vo minere Schwöschter", "s Huus minere Schwöschter"], "why": "No genitive: vo + dative."}, "g26e5": {"q": "Which ending do the feminine and the plural share?", "options": ["-n", "-i", "-s"], "why": "mini Mueter and mini Chind: both with -i."}}},
  "g14": {"title": "The imperative", "summary": "Giving orders and instructions. Two forms: you, and you-plural / polite.", "points": ["To **du**: the bare verb stem, no ending. **Chum!** **Gang!** **Lueg!** **Mach!** **Wart!**", "To **ihr** and to **Sie**: stem + **-ed**. **Chömed!** **Gönd!** **Lueged!** **Mached!**", "With Sie you add the pronoun: **Lueged Sie!** · **Chömed Sie!**", "To soften it: add **bitte**, or turn it into a question — \"**Chöntsch** du…?\"", "Heard constantly in the street: **Lueg mal!** (look!) · **Wart chli!** (wait a sec!)"], "ex": {"g14e1": {"q": "Tell a friend to come: ___! (cho)", "why": "Imperative for du: bare stem → Chum!"}, "g14e2": {"q": "Tell a group to look: ___!", "options": ["Lueg", "Lueged", "Luege"], "why": "Plural and Sie → stem + -ed: Lueged!"}, "g14e3": {"q": "Tell a friend to wait a moment: ___ chli! (warte)", "why": "Wart chli!"}, "g14e4": {"q": "How do you say «please come in» to a client?", "options": ["Chum bitte ine!", "Chömed Sie bitte ine!", "Chömed bitte ine!"], "why": "With Sie: the -ed form + Sie."}, "g14e5": {"q": "Which way of asking is the MOST polite?", "options": ["Gib mer s Salz!", "Gib mer bitte s Salz.", "Chöntsch mer bitte s Salz gää?"], "why": "Turning it into a question with the Konjunktiv is the softest register."}}},
  "g12": {"title": "Question words", "summary": "The seven you need to survive a conversation.", "points": ["**Was?** what · **Wär?** who · **Wo?** where · **Wänn?** when", "**Wie?** how · **Wieso? / Warum?** why · **Wievil?** how much", "Mind the false friend: **Wär** = who (German \"wer\"), NOT \"where\".", "**Wo häre?** = where to · **Wo har?** = where from", "Order: question word + verb + subject. **Wänn chunsch du?**"], "ex": {"g12e1": {"q": "___ heissisch du? (how)", "why": "Wie heissisch du? = What’s your name?"}, "g12e2": {"q": "___ wohnsch du? (where)", "why": "Wo wohnsch du?"}, "g12e3": {"q": "___ isch das? (who)", "options": ["Wo", "Wär", "Was"], "why": "Wär = who. Wo = where."}, "g12e4": {"q": "___ choschtet das? (how much)", "options": ["Wievil", "Was", "Wie"], "why": "Wievil choschtet das? — \"Was choschtet das?\" works too."}, "g12e5": {"q": "___ chunsch du? (when)", "why": "Wänn chunsch du?"}}},
  "s05": {"title": "«Wele…?» or «Was für…?»", "summary": "From the class on 26/08. Two questions that sound the same in English but aren’t.", "points": ["**Wele…?** = which one? You pick from a known set. The answer takes a **definite** article.", "**Was für…?** = what kind of? You ask about the type. The answer takes an **indefinite** article.", "Wele declines with the usual pattern: **wele** (m) · **weli** (f) · **wels** (n) · **weli** (pl)", "**Wele** Bär häsch welle? — **De** Plüschbär! (that one over there)", "**Was für en** Chäs häsch welle? — **En** Weichchäs! (what kind)", "Foolproof trick: if you can answer «that one there», it’s **Wele**. If you answer «a soft one», it’s **Was für**."], "tableHead": ["", "Wele…? (which)", "Was für…? (what kind)"], "ex": {"s05e1": {"q": "___ Bär häsch welle? — De Plüschbär! (masculine)", "why": "Masculine → wele. The definite article in the answer confirms it was «Wele»."}, "s05e2": {"q": "___ Chügelibahn häsch welle? — Die us Holz! (feminine)", "why": "Feminine → weli."}, "s05e3": {"q": "___ Autöli häsch welle? — S rote Autöli!", "options": ["Wele", "Weli", "Wels"], "why": "Autöli is neuter → wels."}, "s05e4": {"q": "Was für ___ Chäs häsch welle? — En Weichchäs.", "options": ["en", "e", "es"], "why": "Was für + indefinite article, and Chäs is masculine → en."}, "s05e5": {"q": "Was für ___ Schoggi? — E Dunkli.", "options": ["en", "e", "es"], "why": "Schoggi is feminine → e."}, "s05e6": {"q": "The answer is «die vo Jura». Which question was it?", "options": ["Weli Kafimaschine macht de bescht Kafi?", "Was für e Kafimaschine macht de bescht Kafi?"], "why": "«die vo Jura» is a definite article: you pick from a set → Weli."}, "s05e7": {"q": "The answer is «es iPhone oder es anders». Which question was it?", "options": ["Wels Smartphon häsch kauft?", "Was für es Smartphon häsch kauft?"], "why": "Indefinite article: you’re asking about the type → Was für."}, "s05e8": {"q": "What’s the trick for telling them apart?", "options": ["The gender of the noun", "The article in the answer", "The position of the verb"], "why": "Definite → Wele. Indefinite → Was für."}}},
  "g27": {"title": "Prepositions and contractions", "summary": "The hard part isn’t the prepositions: it’s the contractions, which are written as one word.", "points": ["Place: **i / im** (in) · **uf / ufem** (on) · **under** · **über** · **näbet** (next to) · **zwüsche** · **vor** · **hinder** · **bi** (at someone’s)", "Time: **am** Mäntig · **im** Summer · **am** achti (clock time) · **sit** · **bis** · **vor** · **nach**", "Cause and purpose: **für** · **wäge** (because of) · **zum** + infinitive (in order to)", "Contractions you need to recognise instantly:", "i + em = **im** · a + em = **am** · zu + em = **zum** · uf + em = **ufem** · bi + em = **bim** · vo + em = **vom** · i + eme = **ime**", "With cities you use **z**: **z** Züri · **z** Bärn (not \"in Zürich\")."], "tableHead": ["Contraction", "From", "Example"], "ex": {"g27e1": {"q": "Ich bi ___ Büro. (at the office)", "why": "i + em = im."}, "g27e2": {"q": "S Buech ligt ___ Tisch.", "options": ["im", "ufem", "zum"], "why": "On the table → uf + em = ufem."}, "g27e3": {"q": "Ich wohne ___ Züri. (in Zurich)", "why": "With cities, \"z\": z Züri."}, "g27e4": {"q": "How do you say «on Monday»?", "options": ["uf Mäntig", "am Mäntig", "im Mäntig"], "why": "Days of the week with \"am\"."}, "g27e5": {"q": "Ich gang ___ Dokter. (to the doctor’s)", "why": "zu + em = zum."}, "g27e6": {"q": "«ime Zug» comes from…", "options": ["i + em", "i + eme", "i + de"], "why": "With the indefinite article: i + eme = ime (on a train)."}}},
  "s04": {"title": "Purpose: zum + infinitive", "summary": "From the class on 19/08. For saying what something is for. Much shorter than in German.", "points": ["Structure: **zum** + infinitive, at the end of the sentence.", "Ich bruuch en Pass **zum reise**. = I need a passport to travel.", "E Massage **zum entspanne**. · En Suugroboter **zum Ziit spare**.", "Ich bruuch en Fründ **zum glücklich sii**.", "German would need «um … zu»: *um zu reisen*. In dialect **zum** is enough.", "If there is an object, it goes in between: zum **d Haar** wäsche · zum **Ziit** spare."], "ex": {"s04e1": {"q": "Ich bruuch en Pass ___ reise. (to)", "why": "zum + infinitive."}, "s04e2": {"q": "How do you say «to save time»?", "options": ["um Ziit zum spare", "zum Ziit spare", "für Ziit spare"], "why": "zum + object + infinitive."}, "s04e3": {"q": "Translate: «I need a friend to be happy.»", "options": ["Ich bruuch e Fründin zum glücklich sii.", "Ich bruuch e Fründin um glücklich zu sii.", "Ich bruuch e Fründin für glücklich sii."], "why": "The dialect doesn’t use «um … zu»."}, "s04e4": {"q": "Was für es Schampoo bruuchsch du ___ d Haar wäsche?", "why": "The object «d Haar» goes between the zum and the infinitive."}, "s04e5": {"q": "Where does the infinitive go?", "options": ["Right after zum", "At the end of the sentence", "At the beginning"], "why": "It closes the sentence, as infinitives always do."}}},
  "h03": {"title": "Where and where to: obsi, nidsi, überobe", "summary": "From the class on 09/09. The dialect uses different words for where you are and where you’re going.", "points": ["Where you are: **daa** (here) · **deet** (there) · **däne**, **deet äne** (over on the other side) · **änet** (on the far side of)", "Where you’re heading, up: **obsi**, **ufe**. Down: **nidsi**, **abe**.", "Forwards: **fürsi**. Backwards: **hindersi**. Over here: **häre**, **da ane**.", "The floors of a house have words of their own:", "**überobe** = upstairs (where you are) · **überune** = downstairs", "**überue** = up to the floor above · **überabe** = down to the floor below", "Notice the pattern: **-obe/-une** is where you are, **-ue/-abe** is where you’re going.", "Two expressions you’ll want: «S gaat gèèch **obsi**» (it climbs steeply) and «Mit dère Firma gaat s **nidsi**» (that company is going downhill)."], "tableHead": ["", "Where you are", "Where you’re going"], "ex": {"h03e1": {"q": "Er isch ___ im Badzimmer. (upstairs, where he is)", "why": "-obe = where you are, up top."}, "h03e2": {"q": "Ich chume grad ___. (I’m coming up now)", "options": ["überobe", "überue", "überune"], "why": "Movement upwards → überue."}, "h03e3": {"q": "Gang jetz äntli ___! (go down already)", "options": ["überune", "überabe", "überobe"], "why": "Movement downwards → überabe."}, "h03e4": {"q": "S gaat gèèch ___. Chum ufe! (upwards)", "why": "obsi = aufwärts."}, "h03e5": {"q": "«Mit dère Firma gaat s nidsi» means…", "options": ["the company is doing very well", "the company is going downhill", "the company is relocating"], "why": "nidsi = downwards, and figuratively that it is going badly."}, "h03e6": {"q": "Mach emaal ___ mit dère Aarbet! (get on with it)", "why": "fürsi = vorwärts, literally «forwards»."}, "h03e7": {"q": "«Die Chile staat ___ der Limet» = the church is on the far side of the Limmat.", "options": ["deet", "änet", "daa"], "why": "änet = jenseits, on the far side of."}, "h03e8": {"q": "What is the pattern for floors?", "options": ["-obe/-une where you are, -ue/-abe where you’re going", "The other way round", "There is no pattern"], "why": "überobe/überune = position · überue/überabe = movement."}}},
  "g28": {"title": "Conjunctions and where the verb goes", "summary": "The conjunction you pick decides where the verb ends up. It’s the rule people forget most.", "points": ["The ones that **don’t** move the verb (it stays second): **und · oder · aber · dänn · sondern**", "Ich bi müed, **aber** ich **chume** trotzdem.", "The ones that **send the verb to the end**: **wil · dass · öb · wenn · wo · öbwohl · bevor · bis · damit**", "Ich chume nöd, **wil** ich chrank **bi**.", "Er het gfrogt, **öb** ich Ziit **han**.", "**dass** is often dropped: \"Ich glaub, er chunt spöter.\" And then the verb stays in second position."], "tableHead": ["Type", "Conjunctions", "The verb goes…"], "ex": {"g28e1": {"q": "Which is correct?", "options": ["Ich blibe deheim, wil ich bi müed.", "Ich blibe deheim, wil ich müed bi.", "Ich blibe deheim, wil bi ich müed."], "why": "\"wil\" is subordinating → the verb closes the sentence."}, "g28e2": {"q": "And with «aber»?", "options": ["…, aber ich chume trotzdem.", "…, aber ich trotzdem chume.", "…, aber chume ich trotzdem."], "why": "\"aber\" moves nothing: the verb stays in second position."}, "g28e3": {"q": "Er het gfrogt, ___ ich Ziit han. (whether)", "why": "\"öb\" = whether, and it sends the verb to the end."}, "g28e4": {"q": "Which conjunction does NOT send the verb to the end?", "options": ["wil", "öbwohl", "oder"], "why": "und/oder/aber/dänn are coordinating."}, "g28e5": {"q": "If you drop the «dass», where does the verb go?", "options": ["Still at the end", "Back to second position", "At the beginning"], "why": "Without \"dass\" the clause stops behaving like a subordinate one: \"Ich glaub, er chunt spöter.\""}}},
  "g19": {"title": "Being in the middle of doing: «am … sii»", "summary": "The dialect does have a way of saying you’re doing something right now. Standard German doesn’t.", "points": ["Structure: conjugated **sii** + **am** + infinitive (capitalised, like a noun).", "Ich **bi am Schaffe**. = I’m working.", "Er **isch am Ässe**. = He’s eating.", "Mir **sind am Luege**. = We’re watching.", "It is the exact parallel of the English continuous, and it’s used a lot.", "Careful: it is not the same as the plain present. \"Ich schaffe\" = I work (in general)."], "ex": {"g19e1": {"q": "Ich ___ am Choche. (I’m cooking)", "why": "sii + am + infinitive: ich bi am Choche."}, "g19e2": {"q": "How do you say «he’s sleeping»?", "options": ["Er schlaft.", "Er isch am Schlafe.", "Er isch schlafe."], "why": "sii + am + infinitive."}, "g19e3": {"q": "What’s the difference between «Ich schaffe» and «Ich bi am Schaffe»?", "options": ["None, they’re synonyms", "The first is general, the second is right now", "The first is past tense"], "why": "\"Ich schaffe\" = I work (in general). \"Ich bi am Schaffe\" = I’m working right now."}, "g19e4": {"q": "Mir ___ am Ässe. (we’re eating)", "why": "Plural of sii: sind."}}},
  "g08": {"title": "The past: the perfect only", "summary": "Good news: Swiss German has NO Präteritum. One single past tense for everything.", "points": ["Forget \"ich machte\", \"ich ging\", \"ich war\". They don’t exist in dialect.", "Formula: conjugated **haa** or **sii** + participle at the end.", "Ich **ha** gmacht. · Ich **bi** gange. · Ich **ha** gässe.", "\"I was\" = **ich bi gsi** (literally \"I have been\"). You simply have to know this one.", "\"I had\" = **ich ha gha**.", "Verbs of motion and change of state take **sii**: gange, cho, blibe, gsi.", "The irregular participles have to be learned by heart: they are all in the topic «The irregular participles»."], "tableHead": ["English", "Züridütsch", "Hochdeutsch"], "ex": {"g08e1": {"q": "Ich ___ geschter z Bärn gsi.", "why": "\"gsi\" (been) always with sii → ich bi gsi."}, "g08e2": {"q": "Mir ___ scho gässe.", "why": "ässe takes haa → mir händ gässe."}, "g08e3": {"q": "How do you say \"I went home\"?", "options": ["Ich ha hei gange.", "Ich bi hei gange.", "Ich ging hei."], "why": "Verb of motion → sii. And the Präteritum doesn’t exist."}, "g08e4": {"q": "Translate \"ich hatte keine Zeit\".", "options": ["Ich hatt kei Ziit.", "Ich ha kei Ziit gha.", "Ich bi kei Ziit gsi."], "why": "\"I had\" = ha ... gha."}, "g08e5": {"q": "Er ___ am Aabig cho.", "why": "cho (to come) is motion → sii: er isch cho."}, "g08e6": {"q": "Which tense does NOT exist in Swiss German?", "options": ["The perfect", "The Präteritum (ich machte)", "The present"], "why": "The Präteritum has vanished from the dialect. The whole past is made with the perfect."}}},
  "h07": {"title": "The irregular participles", "summary": "From the class on 23/09. Without these you can’t speak in the past, and the past is all there is.", "points": ["sii → **gsii** · haa → **ghaa** · gaa → **ggange** · tue → **taa** · gèè → **ggèè** · nèè → **gnaa**", "ässe → **ggässe** · läse → **gläse** · säge → **gsäit** · trääge → **träit** · zie → **zoge**", "träffe → **troffe** · wüsse → **gwüsst** · staa → **gstande** · laa → **glaa** · legge → **gläit** · ligge → **gläge**", "Three that don’t change at all: **choo → choo** · **gsee → gsee**", "⚠️ The modals form the participle **exactly like the infinitive**: wele → **wele** · müese → **müese** · chöne → **chöne** · möge → **möge** · sele → **sele**", "Ich han nöd **chöne** cho. = I couldn’t come. (not «gchönt»)", "Notice that many start with a doubled **g-**: **gg**ange, **gg**èè, **gg**ässe."], "tableHead": ["Infinitive", "Participle", "Example"], "ex": {"h07e1": {"q": "Participle of «gaa»: Mir sind hei ___.", "why": "gaa → ggange."}, "h07e2": {"q": "Participle of «nèè»: Er hät de Zug ___.", "why": "nèè → gnaa."}, "h07e3": {"q": "Participle of «säge»:", "options": ["gsäit", "gsägt", "säge"], "why": "säge → gsäit."}, "h07e4": {"q": "How do you say «I couldn’t come»?", "options": ["Ich han nöd gchönt cho.", "Ich han nöd chöne cho."], "why": "Modals form the participle just like the infinitive."}, "h07e5": {"q": "Participle of «träffe»: Ich han sie ___.", "why": "träffe → troffe."}, "h07e6": {"q": "Which two participles don’t change at all?", "options": ["choo and gsee", "gaa and staa", "ässe and läse"], "why": "choo → choo · gsee → gsee."}, "h07e7": {"q": "Participle of «zie»: Er hät de Wage ___.", "why": "zie → zoge."}, "h07e8": {"q": "Participle of «ligge»:", "options": ["gligge", "gläge", "gläit"], "why": "ligge → gläge. «gläit» is from legge: watch out."}}},
  "g15": {"title": "The future (which doesn’t exist)", "summary": "More good news: the dialect has no future tense. You use the present.", "points": ["Forget \"werden\". In dialect it is hardly ever used to make the future.", "Present + a time word and you have your future:", "**Morn gang ich** uf Bärn. = Tomorrow I’ll go to Bern.", "**Nächscht Wuche fangt** de Kurs **aa**. = The course starts next week.", "Remember the order: if you start with the time word, the verb is still second."], "ex": {"g15e1": {"q": "How do you say «tomorrow I’ll work»?", "options": ["Morn wird ich schaffe.", "Morn schaffe ich.", "Morn ich schaffe."], "why": "Present + \"morn\". And the verb in second position."}, "g15e2": {"q": "How do you say «next year I’ll go to Switzerland»?", "options": ["Nächschts Johr gang ich i d Schwiiz.", "Nächschts Johr werde ich i d Schwiiz gaa.", "Ich gang werde i d Schwiiz."], "why": "Present + time expression."}, "g15e3": {"q": "Fill in the present: Morn ___ ich di aa. (rüefe = to call)", "why": "1st person = the infinitive: rüefe. The prefix \"aa\" goes at the end."}, "g15e4": {"q": "How many past and future tenses does the dialect have?", "options": ["One past and one future", "One past and no future", "Two pasts and one future"], "why": "Only the perfect for the past, and nothing for the future: the present covers it."}}},
  "g29": {"title": "The passive (and how to avoid it)", "summary": "It exists, but the dialect shies away from it. What people actually say is something else.", "points": ["What you’ll really hear is **me** (= \"one\", German \"man\") with the verb in the active:", "**Me** macht das so. = That’s how it’s done. · **Me** seit, es sig guet.", "That is the natural way. When in doubt, go for it.", "The textbook passive does exist, with **werde** + participle: \"S Huus **wird** bout.\"", "ich **wird** · du **wirsch** · er **wird**", "In the past, the participle of werde is **worde**: \"Es **isch** gmacht **worde**.\" = It was done.", "Careful: «werde» works for the passive, but **not** for the future (there is no future)."], "ex": {"g29e1": {"q": "How would a Swiss person say «that’s how it’s done»?", "options": ["Das wird so gmacht.", "Me macht das so.", "Das isch so gmacht."], "why": "Both are understood, but the natural one in dialect uses \"me\"."}, "g29e2": {"q": "Es isch scho gmacht ___. (participle of werde)", "why": "werde → worde. \"Es isch gmacht worde\" = it was done."}, "g29e3": {"q": "What is «werde» NOT used for in dialect?", "options": ["The passive", "The future", "Both"], "why": "The future is made with the present. \"werde\" is left for the passive."}, "g29e4": {"q": "___ seit, das sig nöd eifach. (one says)", "why": "\"me\" (or \"mer\") = man."}, "g29e5": {"q": "«S Huus wird bout» means…", "options": ["The house is being built", "The house will be built", "The house has been built"], "why": "Present passive. The future would need a time word."}}},
  "g18": {"title": "Comparing: grösser, am gröschte", "summary": "Comparative with -er and superlative with «am …-schte».", "points": ["Comparative: adjective + **-er** → gross → **grösser** · schnäll → **schnäller**", "Superlative: **am** + adjective + **-schte** → **am gröschte** · **am schnällschte**", "Irregulars you need to know: guet → **besser** → **am beschte**", "vil → **mee** → **am meischte** · gärn → **lieber** → **am liebschte**", "To compare you use **als**: \"Er isch grösser **als** ich.\"", "\"Ich ha **lieber** Tee\" = I prefer tea."], "tableHead": ["Base", "Comparative", "Superlative"], "ex": {"g18e1": {"q": "Züri isch ___ als Bärn. (gross)", "why": "Comparative: -er."}, "g18e2": {"q": "Das isch ___ Lösig. (the best)", "options": ["di guet", "di beschti", "di mee"], "why": "guet → besser → am beschte / di beschti before a noun."}, "g18e3": {"q": "Ich ha ___ Kaffi als Tee. (I prefer)", "why": "gärn → lieber."}, "g18e4": {"q": "How do you say «he runs faster»?", "options": ["Er springt am schnällschte.", "Er springt schnäller.", "Er springt mee schnäll."], "why": "Comparative with -er, never with \"mee\" in front."}, "g18e5": {"q": "Superlative of «schnäll»: am ___", "why": "am + -schte."}}},
  "g17": {"title": "Relative clauses with «wo»", "summary": "One single word for every relative clause. Here the dialect is far easier than German.", "points": ["German uses der/die/das/den/dem depending on the case. The dialect uses **wo** and that’s it.", "De Maa, **wo** det staht, isch min Nachbar.", "D Frau, **wo** ich gseh han, isch d Chefin.", "S Buech, **wo** ich läse, isch guet.", "**wo** also means \"when\" for the past: \"**Wo** ich chli gsi bi…\" = When I was little…", "As always in a subordinate clause, the verb goes to the end."], "ex": {"g17e1": {"q": "De Zug, ___ am achti fahrt, isch voll.", "why": "Every relative clause uses \"wo\"."}, "g17e2": {"q": "Which is correct?", "options": ["D Frau, die ich kännt han…", "D Frau, wo ich kännt han…", "D Frau, welchi ich kännt han…"], "why": "In dialect die/der/welche aren’t used for relative clauses: only \"wo\"."}, "g17e3": {"q": "Translate: «When I was little, I lived in Barcelona.»", "options": ["Wänn ich chli gsi bi, han ich z Barcelona gwohnt.", "Wo ich chli gsi bi, han ich z Barcelona gwohnt.", "Als ich chli gsi bi, han ich z Barcelona gwohnt."], "why": "For a one-off past, \"wo\" does the job of \"als\". \"Wänn\" is for conditions or repeated things."}, "g17e4": {"q": "Where does the verb go inside the relative clause?", "options": ["In second position", "At the end", "Right after wo"], "why": "Subordinate clause → conjugated verb at the end: \"…, wo ich gseh han.\""}, "g17e5": {"q": "S Huus, ___ mir chauft händ, isch alt.", "why": "wo, always wo."}}},
  "g30": {"title": "Reflexive verbs", "summary": "The pronouns are the ones you already know: mi, di, sich.", "points": ["Accusative: **mi · di · sich · üs · eu · sich**", "Ich freue **mi**. = I’m glad. · Setz **di**! = Sit down! · Er wäscht **sich**.", "When the action is done \"for yourself\", the pronoun goes in the **dative**: **mer · dir · em**", "Ich chaufe **mer** es Buech. = I’m buying myself a book.", "Ich han **mer** es Glacé kauft. = I bought myself an ice cream.", "Reflexives you’ll use a lot: sich **freue** (to be glad), sich **setze** (to sit down), sich **verspöte** (to be late), sich **uskänne** (to know your way around)."], "tableHead": ["Person", "Accusative", "Dative"], "ex": {"g30e1": {"q": "Ich freue ___! (I’m glad)", "why": "1st person reflexive accusative: mi."}, "g30e2": {"q": "Setz ___! (sit down, to a friend)", "why": "Imperative + reflexive for du: Setz di!"}, "g30e3": {"q": "Ich chaufe ___ es nöis Velo. (for myself)", "options": ["mi", "mer", "mich"], "why": "Action for yourself → dative: mer."}, "g30e4": {"q": "How do you say «I’m late»?", "options": ["Ich ha mi verspöted.", "Ich ha mer verspöted.", "Ich bi mi verspöted."], "why": "sich verspöte, with haa and the reflexive in the accusative."}, "g30e5": {"q": "Er wäscht ___. (he washes)", "why": "3rd person: sich."}}},
  "g13": {"title": "Konjunktiv II: wär, hätt, chönt", "summary": "The form of politeness and hypotheses. You’ll use it every day to ask for things.", "points": ["**sii** → ich **wär** · du **wärsch** · er **wär** · mir **wäred**", "**haa** → ich **hätt** · du **hättsch** · er **hätt** · mir **hätted**", "**chöne** → ich **chönt** · du **chöntsch** · er **chönt** · mir **chönted**", "**wölle** → ich **wett** (= I’d like). \"Ich wett es Bier\" is the normal way to order.", "For all other verbs: **wür / würd** + infinitive → \"Ich **wür** säge…\"", "Das **wär** super! · **Chöntsch** mer hälfe? · Ich **hätt** gärn en Kaffi."], "tableHead": ["", "Present", "Konjunktiv II"], "ex": {"g13e1": {"q": "Ich ___ gärn es Glas Wii. (I’d like — from haa)", "why": "\"Ich hätt gärn…\" is THE formula for asking for anything."}, "g13e2": {"q": "___ Sie mer hälfe? (use the Konjunktiv)", "options": ["Chönd", "Chönted", "Chasch"], "why": "Konjunktiv of chöne as a politeness form: chönted Sie. \"Chönd Sie\" (present) is also used, but less soft."}, "g13e3": {"q": "Das ___ super! (would be)", "why": "sii → wär."}, "g13e4": {"q": "How do you say «I’d like to go»?", "options": ["Ich wott gaa.", "Ich wett gaa.", "Ich wär gaa."], "why": "\"wott\" = I want (blunt). \"wett\" = I’d like (polite)."}, "g13e5": {"q": "Wänn ich Ziit ___, wür ich cho.", "options": ["ha", "hätt", "händ"], "why": "Hypothesis → Konjunktiv: wänn ich Ziit hätt."}}},
  "g31": {"title": "Reported speech: seig and häig", "summary": "For when you’re passing on what someone else said and not vouching for it. Two forms you need to recognise.", "points": ["From **sii** comes **seig** · from **haa** comes **häig**.", "Er het gseit, er **seig** chrank. = He said he was ill.", "Sie het gseit, sie **häig** kei Ziit. = She said she had no time.", "Using seig/häig marks distance: **you’re passing it on, not claiming it’s true**.", "With all other verbs the dialect usually just uses the indicative:", "Er het gseit, er **chunt** spöter. = He said he’d come later.", "You’ll hear them above all on the news, in gossip, and when someone is shifting responsibility."], "ex": {"g31e1": {"q": "Er het gseit, er ___ chrank. (from sii)", "why": "sii → seig in reported speech."}, "g31e2": {"q": "Sie het gseit, sie ___ kei Ziit. (from haa)", "why": "haa → häig."}, "g31e3": {"q": "What does «seig» add compared to saying «er isch chrank»?", "options": ["Nothing, it’s just more formal", "That you’re passing it on without vouching for it", "That it’s a lie"], "why": "It marks that you’re quoting someone else, without committing yourself."}, "g31e4": {"q": "With most verbs, how is reported speech made in dialect?", "options": ["With special forms for each verb", "With the plain indicative", "It can’t be done"], "why": "Only sii and haa have everyday forms of their own; the rest go in the indicative."}}},
  "g10": {"title": "The diminutive -li", "summary": "The Swiss make EVERYTHING a diminutive. It doesn’t always mean \"small\": often it’s affection or just habit.", "points": ["You add **-li** to the noun, often with an Umlaut: Huus → H**üü**sli.", "Chind → Chindli · Bier → Bierli · Hund → Hündli · Frau → Fräuli", "Many words ALREADY are fossilised diminutives: **Gipfeli**, **Meitli**, **Müesli**, **Zvieri**.", "Every diminutive is **neuter**: s Hüüsli, s Bierli, s Chindli.", "Careful: overusing it sounds childish. Listen to where native speakers actually use it."], "ex": {"g10e1": {"q": "Diminutive of \"Chind\" → ___", "why": "Chind + li = Chindli."}, "g10e2": {"q": "Diminutive of \"Huus\" → ___", "why": "Huus → Hüüsli (with Umlaut)."}, "g10e3": {"q": "Which article does \"Hüüsli\" take?", "options": ["de", "d", "s"], "why": "Every diminutive is neuter → s Hüüsli."}, "g10e4": {"q": "What is a \"Gipfeli\"?", "options": ["A small summit", "A croissant", "A coin"], "why": "Literally \"little peak\", but it means croissant. A fossilised diminutive."}, "g10e5": {"q": "\"Meitli\" means...", "options": ["girl", "boy", "teacher"], "why": "Meitli = girl (Mädchen). Another fossilised diminutive."}}}
}
